const cssSafeCalendarId = cal.view.formatStringForCSSRule(calendar.id);
this.style.setProperty(
  "--calendar-bar-color",
  `var(--calendar-${cssSafeCalendarId}-backcolor)`
);

this.#title.textContent = event.title;
this.querySelector(".calendar-name").textContent = calendar.name;
this.#title.title = `${calendar.name} - ${event.title}`;

.titlebar {
  --calendar-bar-color-fallback: #1373d9;
  position: relative;
  display: flex;
  align-items: flex-start;
  flex-direction: column;
  overflow: hidden;
  padding: calc(var(--calendar-dialog-title-bar-padding-block) + var(--calendar-dialog-top-bar-height)) var(--calendar-dialog-row-padding-inline)
    var(--calendar-dialog-title-bar-padding-block);
  gap: 4px;

  &::before {
    border-radius: var(--calendar-border-radius) var(--calendar-border-radius) 0 0;
    content: "";
    position: absolute;
    inset-block-start: 0;
    inset-inline: 0;
    block-size: var(--calendar-dialog-top-bar-height);
    background: var(--calendar-bar-color, var(--calendar-bar-color-fallback));
  }

& .calendar-name {
  flex: 1;

  &::before {
    content: "";
    background: var(--calendar-bar-color, var(--calendar-bar-color-fallback));
    inline-size: 9px;
    block-size: 9px;
    margin-inline-end: 9px;
    display: inline-block;
    border-radius: 9px;
  }
